// Keeps the articles not sent before (remembered for 30 days).
const memory = $getWorkflowStaticData('global');
memory.sent = memory.sent || {};
const now = Date.now();
for (const [k, t] of Object.entries(memory.sent)) if (now - t > 30 * 24 * 3600 * 1000) delete memory.sent[k];
const firstRun = Object.keys(memory.sent).length === 0;

const out = [];
const articles = $input.all().map((i) => i.json).filter((a) => a.url)
  .sort((a, b) => String(a.publishedAt).localeCompare(String(b.publishedAt)));
for (const a of articles) {
  if (memory.sent[a.url]) continue;
  memory.sent[a.url] = now;
  if (firstRun) continue; // the first run only fills the memory, so you are not flooded
  out.push({ json: {
    ...a,
    text: `📰 ${a.title}\n${a.source || ''}${a.publishedAt ? ' · ' + a.publishedAt.slice(0, 16).replace('T', ' ') + ' UTC' : ''}\n`
      + `${a.description ? a.description + '\n' : ''}${a.url}`,
  } });
}
return out;
